            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">ANCIENT WISDOM</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">Fever has been respected for millennia</text><rect x=\"100\" y=\"250\" width=\"900\" height=\"300\" rx=\"20\" fill=\"rgba(139,92,246,0.1)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"350\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"28\">Give me the power to produce fever</text><text x=\"550\" y=\"410\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"28\">and I will cure all disease.</text><text x=\"550\" y=\"490\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-size=\"20\">-- attributed to Parmenides</text><rect x=\"150\" y=\"660\" width=\"800\" height=\"150\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"720\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"20\">An overstatement -- but the ancients</text><text x=\"550\" y=\"760\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"20\">saw fever as a helper, not an enemy</text></svg>",
