            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"140\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"200\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">WHY SO WIPED OUT?</text><text x=\"550\" y=\"250\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Tired, foggy, not hungry</text><text x=\"550\" y=\"295\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Who is sending the signal?</text><circle cx=\"550\" cy=\"560\" r=\"140\" fill=\"rgba(245,158,11,0.15)\" stroke=\"#f59e0b\" stroke-width=\"3\"/><text x=\"550\" y=\"550\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"26\">MESSENGERS</text><text x=\"550\" y=\"590\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">to the brain</text><rect x=\"200\" y=\"800\" width=\"700\" height=\"80\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"850\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"20\">Feeling sick is partly a strategy</text></svg>",
            "caption": "Final check: sickness behavior"
